INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var Luthers 95 teser?","options":["Et dokument med 95 argumenter imod den katolske kirkes salg af afladsbreve offentliggjort i 1517","En liste over 95 ting Luther ville aendre i den protestantiske kirke","En religioes lovbog med 95 paragrafer","Et brev til paven med 95 spoergsmaal om kristendom"],"correct":"Et dokument med 95 argumenter imod den katolske kirkes salg af afladsbreve offentliggjort i 1517","accepted_answers":["Et dokument med 95 argumenter imod den katolske kirkes salg af afladsbreve offentliggjort i 1517"],"review_text":"I 1517 offentliggjorde Luther 95 argumenter mod kirkens salg af afladsbreve. Han naglede dem efter sigende op paa kirkedoren i Wittenberg. Teserne spredte sig hurtigt via bogtrykkerkunsten og startede en europaisk religioes revolution."}'::jsonb,
  'mc','short','{"concepts":["95 teser","Wittenberg","afladsbreve","1517"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',1,'auto',true,'reformation_monarchy',7,1
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad gjoerde Frederik III i 1660?","options":["Han indfoerte enevaeldet i Danmark og fjernede adelens politiske magt","Han grundlagde den lutherske kirke i Danmark","Han underskrev grundloven og indfoerte demokrati","Han afskaffede Reformationen og genindfoerte katolicisme"],"correct":"Han indfoerte enevaeldet i Danmark og fjernede adelens politiske magt","accepted_answers":["Han indfoerte enevaeldet i Danmark og fjernede adelens politiske magt"],"review_text":"I 1660 sammenkaldte Frederik III Staenderforsamlingen. I en historisk vending stemte adel, borger og praester for at give kongen enevaeldig magt. Adelens politiske privilegier forsvandt. Kongen styrerede nu uden rival."}'::jsonb,
  'mc','short','{"concepts":["Frederik III","enevaelde","1660","Staenderforsamling","adelen"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',1,'auto',true,'reformation_monarchy',7,1
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var adelens rolle i det danske samfund foer enevaeldet?","options":["Adelen var store jordejere med arvelige privilegier og politisk magt som kongen maatte forhandle med","Adelen var praester og kirkeledere der kontrollerede religionen","Adelen var koebmaend og haandvaerkere der styrede okonomien","Adelen var en militaer enhed der kun kaempede for kongen"],"correct":"Adelen var store jordejere med arvelige privilegier og politisk magt som kongen maatte forhandle med","accepted_answers":["Adelen var store jordejere med arvelige privilegier og politisk magt som kongen maatte forhandle med"],"review_text":"Adelen arvede privilegier som skattefrihed og ret til at sidde i Rigsraadet der raadgav kongen. De ejede store godser og kontrollerede boenderne. Foer enevaeldet var adelen kongens vigtigste rivalmagt."}'::jsonb,
  'mc','short','{"concepts":["adelen","privilegier","Rigsraadet","godser","rivalmagt"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',1,'auto',true,'reformation_monarchy',7,1
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad betod det lutherske princip om frelse ved tro alene?","options":["At mennesket frelstes af sin tro paa Gud og ikke ved at kobe afladsbreve eller goere gode gerninger","At kun praester kunne opnaa frelse","At frelse kraevede pilgrimsrejse til Rom","At frelse kraevede at man betalte en aarslig afgift til kirken"],"correct":"At mennesket frelstes af sin tro paa Gud og ikke ved at kobe afladsbreve eller goere gode gerninger","accepted_answers":["At mennesket frelstes af sin tro paa Gud og ikke ved at kobe afladsbreve eller goere gode gerninger"],"review_text":"Luther laeste Paulus og forstod det saadan: Gud giver naade til den der tror ikke til den der betaler. Afladsbreve var meningsloese. Tro alene var nok. Det var en fundamental omvaeltning af kirkens system."}'::jsonb,
  'mc','short','{"concepts":["frelse","tro alene","afladsbreve","naade","Luther"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',1,'auto',true,'reformation_monarchy',7,1
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var en livegen bonde i Danmark?","options":["En bonde der var bundet til et bestemt gods og ikke maatte flytte uden herremandens tilladelse","En bonde der ejede sin jord og betalte skat til kongen","En fri bonde der arbejdede for loen paa andres gaarde","En byboer der dyrkede en lille have"],"correct":"En bonde der var bundet til et bestemt gods og ikke maatte flytte uden herremandens tilladelse","accepted_answers":["En bonde der var bundet til et bestemt gods og ikke maatte flytte uden herremandens tilladelse"],"review_text":"Livegne boender var bundne til godset. De maatte ikke flytte. De maatte ikke gifte sig uden herremandens tilladelse. De betalte afgifter i korn og arbejde. De var juridisk bundet til den jord de dyrkede."}'::jsonb,
  'mc','short','{"concepts":["livegen","bonde","gods","afgifter","binding"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',1,'auto',true,'reformation_monarchy',7,1
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad er en statskirke?","options":["En kirke der er officielt forbundet med staten og kongen er dens overhoved","En kirke der finansierer staten via skatter","En kirke der er placeret i landets hovedstad","En kirke der er grundlagt af en konges beslutning men ellers er selvstaendig"],"correct":"En kirke der er officielt forbundet med staten og kongen er dens overhoved","accepted_answers":["En kirke der er officielt forbundet med staten og kongen er dens overhoved"],"review_text":"I Danmark efter Reformationen var kirken statskirke. Kongen var kirkens overhoved. Praesterne var statsansatte. Gudstjenestens indhold var bestemt af staten. Kirke og stat var smeltet samman i eet system."}'::jsonb,
  'mc','short','{"concepts":["statskirke","stat og kirke","kongens overhoved","sammensmeltet"],"misconception_type":"false_equivalence","cognitive_skill":"recall","difficulty_type":"factual","insight_type":"conceptual_bridge","challenge_role":"reinforcement","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',1,'auto',true,'reformation_monarchy',7,1
);

