INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var bogtrykkerkunstens konkrete rolle i Reformationens spredning?","options":["Luthers skrifter og bibelen paa folkesprog kunne masseproduceres og naae laesere over hele Europa paa kort tid","Bogtrykkerkunsten hjalp paven med at udsende modargumenter hurtigere","Bogtrykkerkunsten var irrelevant fordi de fleste ikke kunne laese","Bogtrykkerkunsten bredte kun Reformationen til Sydtyskland"],"correct":"Luthers skrifter og bibelen paa folkesprog kunne masseproduceres og naae laesere over hele Europa paa kort tid","accepted_answers":["Luthers skrifter og bibelen paa folkesprog kunne masseproduceres og naae laesere over hele Europa paa kort tid"],"review_text":"Gutenbergs trykkepresse fra 1450 var afgoorende. Luthers tekster kunne massereproduceres. Bibeloversaettelse til folkesprog betod at laesere selv kunne studere Guds ord. Reformationen var den forste store massemediebegivenhed i historien."}'::jsonb,
  'mc','short','{"concepts":["bogtrykkeri","masseproduktion","folkesprog","Luther","spredning"],"misconception_type":"causal_inversion","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',2,'auto',true,'reformation_monarchy',7,2
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvorfor var det muligt for Frederik III at indfoere enevaeldet i 1660?","options":["Adelen var svaeekket af krige og gaeld og borgerskabet og praestestanden allierede sig med kongen mod adelen","Frederik III truede adelen militaert og tvang dem til at underskrive","Folket kraevede enevaelde ved en folkeafstemning","Paven beordrede enevaeldet som betingelse for fred"],"correct":"Adelen var svaeekket af krige og gaeld og borgerskabet og praestestanden allierede sig med kongen mod adelen","accepted_answers":["Adelen var svaeekket af krige og gaeld og borgerskabet og praestestanden allierede sig med kongen mod adelen"],"review_text":"Danmark havde tabt krige mod Sverige og adelen var baade svaeekket og hadet for ikke at betale skat. Frederik III spillede borgerskabet og praestestanden ud mod adelen. Da Staenderforsamlingen moodtes i 1660 var stemningen gunstig for kongen."}'::jsonb,
  'mc','short','{"concepts":["Frederik III","enevaelde","adelen svaeekket","borgerskab","alliancer"],"misconception_type":"causal_inversion","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',2,'auto',true,'reformation_monarchy',7,2
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad skete der med adelens privilegier da enevaeldet blev indfoert i 1660?","options":["Adelen mistede sin arvelige ret til politisk indflydelse og blev nu ligesom alle andre underlagt kongens vilje","Adelen bevarede al politisk magt men maattes dele det med borgerskabet","Adelen fik mere magt da kongen beloennede dem for at acceptere enevaeldet","Adelen forsvandt fuldstaendigt som klasse"],"correct":"Adelen mistede sin arvelige ret til politisk indflydelse og blev nu ligesom alle andre underlagt kongens vilje","accepted_answers":["Adelen mistede sin arvelige ret til politisk indflydelse og blev nu ligesom alle andre underlagt kongens vilje"],"review_text":"Foer 1660 sad adelen i Rigsraadet og kunne bremse kongen. Efter 1660 eksisterede Rigsraadet ikke laengere. Adelen beholdt sine godser og sociale privilegier men den politiske magt var vaek. Kongen regerede nu alene."}'::jsonb,
  'mc','short','{"concepts":["adelen","Rigsraadet","privilegier","enevaelde","magtfald"],"misconception_type":"false_equivalence","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',2,'auto',true,'reformation_monarchy',7,2
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var Reformationens konsekvens for uddannelse i Danmark?","options":["Det lutherske krav om at folk selv kunne laese bibelen skabte gradvist bredere adgang til skoleundervisning","Reformationen lukkede alle skoler fordi kirken ikke laengere maatte drive dem","Uddannelse forblev eksklusivt for adelen og hoejere borgerskab","Alle born fik skolegang straks efter Reformationen i 1536"],"correct":"Det lutherske krav om at folk selv kunne laese bibelen skabte gradvist bredere adgang til skoleundervisning","accepted_answers":["Det lutherske krav om at folk selv kunne laese bibelen skabte gradvist bredere adgang til skoleundervisning"],"review_text":"Det tok tid. Men Luthers ide om at alle kristne selv skulle kunne laese bibelen var motor for skoleundervisning. I 1739 indfoerte Danmark lovpligtig skoleundervisning. Reformationens ide om laasekompetence var en vigtig baggrund."}'::jsonb,
  'mc','short','{"concepts":["uddannelse","laesning","bibelen","skoleundervisning","1739"],"misconception_type":"temporal_confusion","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',2,'auto',true,'reformation_monarchy',7,2
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad betod det at kirken og staten smeltede samman under enevaeldet?","options":["Kongen bestemte baaede over love og gudstjenester og praesterne var statsansatte der forkyndte lydighed","Kirken og staten var adskilt og paavirket ikke hinanden","Kirken styrede staten og praesterne var den reelle regering","Staten finansierede kirken men ellers var de uafhaengige"],"correct":"Kongen bestemte baaede over love og gudstjenester og praesterne var statsansatte der forkyndte lydighed","accepted_answers":["Kongen bestemte baaede over love og gudstjenester og praesterne var statsansatte der forkyndte lydighed"],"review_text":"Under enevaeldet var kongen Guds stedfortræder paa jord. Kongens love var Guds vilje. Praesterne forkyndte kongens budskaber. Kirken var statens ideologiske apparat. Det var en fundamental sammensmeltning af religioes og politisk magt."}'::jsonb,
  'mc','short','{"concepts":["stat og kirke","sammensmeltet","kongens magt","religioes legitimitet","enevaelde"],"misconception_type":"scope_confusion","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',2,'auto',true,'reformation_monarchy',7,2
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvorfor profiterede boenderne ikke paa Reformationen?","options":["Fordi den religiose og politiske revolution i toppen ikke aendrede de okonomiske og juridiske betingelser for boendernes liv","Fordi boender var mod Reformationen og derfor straffedes de","Fordi boender allerede levede saa godt at der intet var at forbedre","Fordi boender ikke var paavirket af religion overhovedet"],"correct":"Fordi den religiose og politiske revolution i toppen ikke aendrede de okonomiske og juridiske betingelser for boendernes liv","accepted_answers":["Fordi den religiose og politiske revolution i toppen ikke aendrede de okonomiske og juridiske betingelser for boendernes liv"],"review_text":"Reformationen aendrede hvem der kontrollerede kirken. Enevaeldet aendrede hvem der havde politisk magt. Men bondens afgifter, pligter og bundhed til godset forblev. De store magtpolitiske omvaeltninger passerede over boendernes hoveder."}'::jsonb,
  'mc','short','{"concepts":["boender","Reformation","okonomisk uforandret","pligter","godset"],"misconception_type":"scope_confusion","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',2,'auto',true,'reformation_monarchy',7,2
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var den protestantiske kirkes revolutionaere ide om den troende og Gud?","options":["At hvert enkelt menneske havde en direkte linje til Gud uden behov for kirkens praester og sakramenter som mellemled","At kun kongen kunne tale direkte med Gud","At Gud var utilgaengelig for alle undtagen biskopper","At den troende maatte betale for adgang til Guds naade"],"correct":"At hvert enkelt menneske havde en direkte linje til Gud uden behov for kirkens praester og sakramenter som mellemled","accepted_answers":["At hvert enkelt menneske havde en direkte linje til Gud uden behov for kirkens praester og sakramenter som mellemled"],"review_text":"Katolsk teologi placerede praesten som noedvendig mellemled til Gud. Luther sagde dette var forkert. Tro alene var nok. Det frigjoerde den troende fra kirkens monopol paa det hellige og var revolutionaert."}'::jsonb,
  'mc','short','{"concepts":["direkte linje","Gud","tro","praestens monopol","revolution"],"misconception_type":"causal_inversion","cognitive_skill":"comprehension","difficulty_type":"conceptual","insight_type":"reframing","challenge_role":"reinforcement","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',2,'auto',true,'reformation_monarchy',7,2
);

