INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad er forkert ved forestillingen om at enevaeldet betod at kongen kunne goere praecis hvad han ville?","options":["Kongen var stadig bundet af loven og Guds lov og tradition selvom ingen menneskelig institution officielt kunne stoppe ham","Forestillingen er korrekt enevaeldige konger kunne goere praecis hvad de ville","Det er forkert fordi adelen stadig begraensede kongen under enevaeldet","Det er forkert fordi paven stadig had magt over den danske kongen"],"correct":"Kongen var stadig bundet af loven og Guds lov og tradition selvom ingen menneskelig institution officielt kunne stoppe ham","accepted_answers":["Kongen var stadig bundet af loven og Guds lov og tradition selvom ingen menneskelig institution officielt kunne stoppe ham"],"review_text":"Enevaeldet var juridisk absolutt. Men konger var i teorien bundet af naturretten og Guds lov. Praktisk set ville en tyrannisk kongen risikere revolution eller mord. Konger der regerede stabilt og forstandigt overlevede laengere."}'::jsonb,
  'mc','short','{"concepts":["enevaelde","begraensninger","Guds lov","naturret","misconception-ubegreanset-magt"],"misconception_type":"overgeneralization","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',3,'auto',true,'reformation_monarchy',7,3
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad viser Reformationens politiske og okonomiske dimension om dens egentlige karakter?","options":["At Reformationen var baaede en religioes revolution og en magtpolitisk omfordeling der styrkede natinoalstater paa bekostning af paven","At Reformationen var en rent religioes begivenhed uden politiske konsekvenser","At Reformationens politiske dimension var langt vigtigere end den religiose","At Reformationen kun had okonomiske aarsager og ingen religiose"],"correct":"At Reformationen var baaede en religioes revolution og en magtpolitisk omfordeling der styrkede natinoalstater paa bekostning af paven","accepted_answers":["At Reformationen var baaede en religioes revolution og en magtpolitisk omfordeling der styrkede natinoalstater paa bekostning af paven"],"review_text":"Den politiske dimension var mindst ligesaa vigtig som den religiose. Konger broed med paven og overtog kirkens jord. Nationalstater voksede frem uafhaengige af Roms autoritet. Reformationen remappede Europas magtgeografi."}'::jsonb,
  'mc','short','{"concepts":["Reformation","politisk dimension","ejendom","nationalstater","dobbeltkarakter"],"misconception_type":"scope_confusion","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',3,'auto',true,'reformation_monarchy',7,3
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad er forkert ved forestillingen om at Luther alene skabte Reformationen?","options":["Luther var en udslagsgivende person men Reformationen lykkedes fordi mange var utilfredse med kirken og fyrster had okonomisk interesse i at stoette den","Forestillingen er korrekt Luther alene skabte Reformationen","Det er forkert fordi Luther faktisk ikke spillede nogen rolle","Det er forkert fordi Reformationen startede i Danmark ikke i Tyskland"],"correct":"Luther var en udslagsgivende person men Reformationen lykkedes fordi mange var utilfredse med kirken og fyrster had okonomisk interesse i at stoette den","accepted_answers":["Luther var en udslagsgivende person men Reformationen lykkedes fordi mange var utilfredse med kirken og fyrster had okonomisk interesse i at stoette den"],"review_text":"Luther var vigtig men Reformationen ville ikke have lykkedes uden bogtrykkerkunsten, uden beskyttelse fra tyske fyrstere og uden den brede folkelige utilfredshed med kirkens korruption. Historiske forandringer kraever strukturelle betingelser ikke blot enkeltpersoner."}'::jsonb,
  'mc','short','{"concepts":["Luther","enkeltperson","strukturelle betingelser","fyrstere","misconception-Luther-alene"],"misconception_type":"overgeneralization","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',3,'auto',true,'reformation_monarchy',7,3
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var konsekvenserne af enevaeldet for hverdagslivet for en dansk borger i 1700-tallet?","options":["Lov og orden forbedrede handel og sikkerhed men borgeren havde ingen politisk stemme og var underlagt statens kontrol via kirke og lov","Borgerne levede i frihed og velstand under enevaeldet","Enevaeldet betod konstant terror og borgerne levede i frygt","Borgerne maerkede slet ikke at der var enevaelde"],"correct":"Lov og orden forbedrede handel og sikkerhed men borgeren havde ingen politisk stemme og var underlagt statens kontrol via kirke og lov","accepted_answers":["Lov og orden forbedrede handel og sikkerhed men borgeren havde ingen politisk stemme og var underlagt statens kontrol via kirke og lov"],"review_text":"Enevaeldet bragte ensartede love og reducerede adelens lokale vilkaarlighed. Handel og haandvaerk blomstrede. Men borgeren stemte ikke. Han adlod kongens love. Kirken forkyndte lydighed. Friheden var okonomisk ikke politisk."}'::jsonb,
  'mc','short','{"concepts":["borger","enevaelde","hverdagsliv","handel","politisk frihed"],"misconception_type":"false_equivalence","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',3,'auto',true,'reformation_monarchy',7,3
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad er forbindelsen mellem Reformationen og den gradvise forbedring af laesekompetencer i Europa?","options":["Luthersk kristendom kraevede at den troende selv kunne laese bibelen og det skabte grundlag for skoleundervisning der gradvist naaede bredere befolkningsgrupper","Reformationen forringede laesekompetencer fordi kirken lukkede skolerne","Der er ingen forbindels laesekompetence og Reformationen er uafhaengige","Kun adelen opnaaede laesekompetence som resultat af Reformationen"],"correct":"Luthersk kristendom kraevede at den troende selv kunne laese bibelen og det skabte grundlag for skoleundervisning der gradvist naaede bredere befolkningsgrupper","accepted_answers":["Luthersk kristendom kraevede at den troende selv kunne laese bibelen og det skabte grundlag for skoleundervisning der gradvist naaede bredere befolkningsgrupper"],"review_text":"Den lutherske ide om det almene praestedoemme betod at hvert menneske ideelt set burde kunne laese Guds ord selv. Det skaabte en ideologisk motor for skoleundervisning. Gradvist over generationer naaede dette bredt ud."}'::jsonb,
  'mc','short','{"concepts":["laesekompetence","bibelen","skoleundervisning","almene praestedoemme","Reformation"],"misconception_type":"causal_inversion","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',3,'auto',true,'reformation_monarchy',7,3
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad er forkert ved forestillingen om at demokrati kom hurtigt efter enevaeldet?","options":["Enevaeldet varede i Danmark fra 1660 til 1849 og vejen dertil gik via Oplysning, revolutioner og gradvist pres for forfatning","Forestillingen er korrekt demokrati kom straks efter enevaeldet","Det er forkert fordi Danmark aldrig haft enevaelde","Det er forkert fordi demokratiet kom foer enevaeldet"],"correct":"Enevaeldet varede i Danmark fra 1660 til 1849 og vejen dertil gik via Oplysning, revolutioner og gradvist pres for forfatning","accepted_answers":["Enevaeldet varede i Danmark fra 1660 til 1849 og vejen dertil gik via Oplysning, revolutioner og gradvist pres for forfatning"],"review_text":"Fra 1660 til 1849 var Danmark enevaeldigt monarki. 189 aar. Oplysningstidens ideer om borgerrettigheder, den franske revolution og voksende borgerlig presse skabte langsomt betingelserne. Grundloven i 1849 var resultatet af et laangt historisk forloob."}'::jsonb,
  'mc','short','{"concepts":["demokrati","enevaelde","1849","Grundloven","langsom forandring"],"misconception_type":"temporal_confusion","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"reframing","challenge_role":"challenge","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',3,'auto',true,'reformation_monarchy',7,3
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad viser adelens reaktion paa enevaeldet om forholdet mellem magt og klasse?","options":["Adelen forsoegte at modstaa enevaeldet fordi det truede de arvelige privilegier der had givet dem magt og rigdom i generationer","Adelen bejede enevaeldet enthusiastisk fordi det gav dem mere magt","Adelen var indifferent og lod kongen tage magten uden modstand","Adelen eksisterede ikke som klasse i 1660"],"correct":"Adelen forsoegte at modstaa enevaeldet fordi det truede de arvelige privilegier der had givet dem magt og rigdom i generationer","accepted_answers":["Adelen forsoegte at modstaa enevaeldet fordi det truede de arvelige privilegier der had givet dem magt og rigdom i generationer"],"review_text":"Adelen vidste hvad enevaeldet ville koste dem: Rigsraadet, skattefriheden og den formelle ret til at raadgive kongen. Mange forsoegte at forhandle. Men i 1660 var de for svaekkede af krige og gaeld til at modstaa."}'::jsonb,
  'mc','short','{"concepts":["adelen","enevaelde","privilegier","modstand","klasse"],"misconception_type":"false_equivalence","cognitive_skill":"analysis","difficulty_type":"analytical","insight_type":"perspective_shift","challenge_role":"challenge","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',3,'auto',true,'reformation_monarchy',7,3
);

-- ─── GRADE 7 · BAND 4 (5 questions) ─────────────────────────────────────────

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Var Reformationen en befrielse for det menige folk?","options":["Delvist: religioes befrielse ved at fjerne kirkens monopol paa Guds ord men ingen social eller politisk befrielse for boender og fattige","Ja Reformationen befriede alle sociale klasser fra undertrykkelse","Nej Reformationen forvaerrede livet for alle undtagen kongen","Reformationen var irrelevant for det menige folk"],"correct":"Delvist: religioes befrielse ved at fjerne kirkens monopol paa Guds ord men ingen social eller politisk befrielse for boender og fattige","accepted_answers":["Delvist: religioes befrielse ved at fjerne kirkens monopol paa Guds ord men ingen social eller politisk befrielse for boender og fattige"],"review_text":"Reformationen gav folk et gudstjenesteliv de forstod. Men den gav dem ikke jord, frihed eller stemmeret. Den religiose frigoerelse var reel men den okonomiske og politiske frigoerelse kom ikke. Det er Reformationens paradoks."}'::jsonb,
  'mc','short','{"concepts":["befrielse","religioes frigoerelse","social uforandret","Reformationens paradoks"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"applied","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',4,'auto',true,'reformation_monarchy',7,4
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var Reformationen og enevaeldet set fra kongens, adelens og bondens perspektiv?","options":["Kongen: magt og rigdom. Adelen: tab af politiske privilegier. Bonden: religioes forandring men okonomisk uforandret.","Alle tre grupper oplevede det som en ren forbedring","Alle tre grupper oplevede det som ren undertrykkelse","Kun kongen og adelen var paavirket boenderne var fuldstaendigt uberort"],"correct":"Kongen: magt og rigdom. Adelen: tab af politiske privilegier. Bonden: religioes forandring men okonomisk uforandret.","accepted_answers":["Kongen: magt og rigdom. Adelen: tab af politiske privilegier. Bonden: religioes forandring men okonomisk uforandret."],"review_text":"Reformationen og enevaeldet rammer alle tre grupper vidt forskelligt. Kongen vinder enormt paa begge. Adelen vinder paa Reformationen men taber paa enevaeldet. Bonden faar et gudstjenesteliv han forstaar men beholder sine afgifter og pligter."}'::jsonb,
  'mc','short','{"concepts":["tre perspektiver","kongen","adelen","bonden","Reformation og enevaelde"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"applied","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',4,'auto',true,'reformation_monarchy',7,4
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var forbindelsen mellem Reformationens ide om individets samvittighed og Oplysningstiden 200 aar senere?","options":["Reformationens ide om at den troende selv kan fortolke Guds ord lagde grundlaget for Oplysningstiden ide om at individet ogsaa kan bruge sin fornuft til at kritisere monarker og traditioner","Der er ingen forbindels de to perioder er fuldstaendigt uafhaengige","Reformationen forhindrede Oplysning ved at saette Bibelen over fornuften","Oplysningstiden afviste Reformationens ideer fuldstaendigt"],"correct":"Reformationens ide om at den troende selv kan fortolke Guds ord lagde grundlaget for Oplysningstiden ide om at individet ogsaa kan bruge sin fornuft til at kritisere monarker og traditioner","accepted_answers":["Reformationens ide om at den troende selv kan fortolke Guds ord lagde grundlaget for Oplysningstiden ide om at individet ogsaa kan bruge sin fornuft til at kritisere monarker og traditioner"],"review_text":"Luther sagde: individets samvittighed over kirkens autoritet. Oplysningsfilosofferne sagde: individets fornuft over kongens autoritet. Begge satte individet over den etablerede institution. Det er ikke tilfaeldigt at Oplysning blomstrede i protestantiske lande."}'::jsonb,
  'mc','short','{"concepts":["individuel samvittighed","Oplysning","fornuft","autoritet","kontinuitet"],"misconception_type":"temporal_confusion","cognitive_skill":"evaluation","difficulty_type":"applied","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',4,'auto',true,'reformation_monarchy',7,4
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad betod laeren om at kongens magt kom fra Gud?","options":["At modsaette sig kongen var det samme som at modsaette sig Guds vilje og det legitimerede enevaeldet som religioes pligt","At paven udpegede kongen og dermed beholdt paven al politisk magt","At kongen var Gud og maatte tilbedes som en religioes skikkelse","At kongen ikke behoevede at folge nogen love fordi Gud bestemte alt"],"correct":"At modsaette sig kongen var det samme som at modsaette sig Guds vilje og det legitimerede enevaeldet som religioes pligt","accepted_answers":["At modsaette sig kongen var det samme som at modsaette sig Guds vilje og det legitimerede enevaeldet som religioes pligt"],"review_text":"Laeren om kongens guddomsgivne magt var enevaeldets ideologiske fundament. At nagte at adlyde kongen var at nagte at adlyde Gud. Praesterne forkyndte lydighed til kongen fra praeekestolen. Kirken og staten forstaearkede hinanden gensidigt."}'::jsonb,
  'mc','short','{"concepts":["guddomsret","kongens magt","religioes legitimitet","enevaelde","lydighed"],"misconception_type":"scope_confusion","cognitive_skill":"evaluation","difficulty_type":"applied","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',4,'auto',true,'reformation_monarchy',7,4
);

INSERT INTO public.questions (content, answer_format, answer_type, metadata, type, difficulty, question_type, is_active, learning_objective, target_grade, difficulty_band) VALUES (
  '{"question":"Hvad var saerligt ved den danske vej gennem Reformation og enevaelde?","options":["I Danmark skete begge via kongens beslutning ovenfra ikke via folkelig revolution nedefra og det formede en stærk stat-kirke-alliance der varte ved i aarhundreder","Danmark var det eneste land der nagtede Reformationen og forblev katolsk laengst","Danmark fik enevaelde via folkelig revolution som i Frankrig","Den danske Reformation og enevaelde var identiske med alle andre europaeiske laandes"],"correct":"I Danmark skete begge via kongens beslutning ovenfra ikke via folkelig revolution nedefra og det formede en stærk stat-kirke-alliance der varte ved i aarhundreder","accepted_answers":["I Danmark skete begge via kongens beslutning ovenfra ikke via folkelig revolution nedefra og det formede en stærk stat-kirke-alliance der varte ved i aarhundreder"],"review_text":"I lande som England og Frankrig var Reformationen og magtskiftet mere konfliktfyldt og blodigt. I Danmark kom begge igennem kongens beslutning ovenfra. Det formede en tradition for stærk statslig styring og konsensus der kan spordes frem til i dag."}'::jsonb,
  'mc','short','{"concepts":["dansk vej","ovenfra","stat-kirke-alliance","konsensus","tradition"],"misconception_type":"false_equivalence","cognitive_skill":"evaluation","difficulty_type":"applied","insight_type":"perspective_shift","challenge_role":"deep_challenge","domain":"reformation_monarchy"}'::jsonb,
  'mc_single',4,'auto',true,'reformation_monarchy',7,4
);;
